<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Bouncing Ball Game</title>
    <style>
        body {
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            margin: 0;
            background-color: #f0f0f0;
        }
        canvas {
            border: 2px solid #333;
            background-color: #ffffff;
        }
    </style>
</head>
<body>

    <canvas id="gameCanvas" width="600" height="400"></canvas>

    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        // Ball properties
        let ball = {
            x: canvas.width / 2,
            y: canvas.height / 2,
            radius: 15,
            dx: 3, // velocity in x direction
            dy: 3  // velocity in y direction
        };

        // Function to draw the ball
        function drawBall() {
            ctx.beginPath();
            ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
            ctx.fillStyle = "#0095DD";
            ctx.fill();
            ctx.closePath();
        }

        // Function to update the ball's position and handle bouncing
        function update() {
            // 1. Update position
            ball.x += ball.dx;
            ball.y += ball.dy;

            // 2. Collision detection (Horizontal walls)
            if (ball.x + ball.radius > canvas.width || ball.x - ball.radius < 0) {
                ball.dx = -ball.dx; // Reverse horizontal direction
            }

            // 3. Collision detection (Vertical walls)
            if (ball.y + ball.radius > canvas.height || ball.y - ball.radius < 0) {
                ball.dy = -ball.dy; // Reverse vertical direction
            }

            // Redraw the scene
            draw();
        }

        // Main drawing function
        function draw() {
            // Clear the canvas on every frame
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Draw the ball
            drawBall();
        }

        // Game loop using requestAnimationFrame
        function gameLoop() {
            update();
            requestAnimationFrame(gameLoop);
        }

        // Start the game
        gameLoop();

    </script>

</body>
</html>
