<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Click the Target Game</title>
    <style>
        body {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            min-height: 100vh;
            margin: 0;
            background-color: #f0f0f0;
            font-family: Arial, sans-serif;
        }
        #game-container {
            background-color: #fff;
            border: 2px solid #333;
            box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
            padding: 20px;
            border-radius: 10px;
        }
        canvas {
            border: 1px solid #ccc;
            background-color: #eee;
        }
        #score-board {
            margin-top: 15px;
            font-size: 1.5em;
            font-weight: bold;
            color: #333;
        }
    </style>
</head>
<body>

    <div id="game-container">
        <h1>Click the Moving Target!</h1>
        <canvas id="gameCanvas" width="600" height="400"></canvas>
        <div id="score-board">Score: 0</div>
    </div>

    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        const scoreDisplay = document.getElementById('score-board');

        let score = 0;
        let target = {
            x: 0,
            y: 0,
            size: 20,
            speed: 3,
            direction: 1 // 1 for right, -1 for left
        };

        // --- Game Initialization ---
        function initializeGame() {
            target.x = canvas.width / 2;
            target.y = canvas.height / 2;
            score = 0;
            scoreDisplay.textContent = `Score: ${score}`;
            draw(); // Initial draw
        }

        // --- Drawing Functions ---
        function drawTarget() {
            ctx.fillStyle = 'red';
            ctx.beginPath();
            ctx.arc(target.x, target.y, target.size, 0, Math.PI * 2);
            ctx.fill();
        }

        function draw() {
            // Clear the canvas
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Draw the target
            drawTarget();
        }

        // --- Movement Logic ---
        function updateTargetPosition() {
            // Move the target
            target.x += target.speed * target.direction;

            // Check boundaries and reverse direction
            if (target.x + target.size > canvas.width || target.x - target.size < 0) {
                target.direction *= -1; // Reverse direction
            }
        }

        // --- Click Handling ---
        function handleClick(event) {
            // Get click coordinates relative to the canvas
            const rect = canvas.getBoundingClientRect();
            const clickX = event.clientX - rect.left;
            const clickY = event.clientY - rect.top;

            // Check if the click is within the target's radius
            const distance = Math.sqrt(
                Math.pow(clickX - target.x, 2) + Math.pow(clickY - target.y, 2)
            );

            if (distance < target.size) {
                score++;
                scoreDisplay.textContent = `Score: ${score}`;
                // Reset target position after a successful click (optional, but makes the game more dynamic)
                target.x = canvas.width / 2;
                target.y = canvas.height / 2;
            }
        }

        // --- Game Loop ---
        function gameLoop() {
            updateTargetPosition();
            draw();
            requestAnimationFrame(gameLoop);
        }

        // --- Event Listener Setup ---
        canvas.addEventListener('click', handleClick);

        // Start the game
        initializeGame();
        gameLoop();

    </script>

</body>
</html>
