<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Canvas Square Mover</title>
    <style>
        body {
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            margin: 0;
            background-color: #f0f0f0;
        }
        canvas {
            border: 2px solid #333;
            background-color: #ffffff;
        }
    </style>
</head>
<body>

    <canvas id="gameCanvas" width="600" height="400"></canvas>

    <script>
        // --- Canvas Setup ---
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        // --- Game Variables ---
        const square = {
            x: 50,
            y: 180,
            width: 50,
            height: 50,
            speed: 5,
            color: 'blue'
        };

        // State tracking for movement
        const keys = {
            left: false,
            right: false
        };

        // --- Input Handling ---

        document.addEventListener('keydown', (e) => {
            if (e.key === 'ArrowLeft') {
                keys.left = true;
            } else if (e.key === 'ArrowRight') {
                keys.right = true;
            }
        });

        document.addEventListener('keyup', (e) => {
            if (e.key === 'ArrowLeft') {
                keys.left = false;
            } else if (e.key === 'ArrowRight') {
                keys.right = false;
            }
        });

        // --- Game Logic ---

        function update() {
            // Check for movement based on key states
            if (keys.left) {
                square.x -= square.speed;
            }
            if (keys.right) {
                square.x += square.speed;
            }

            // Boundary checks (keep the square within the canvas)
            if (square.x < 0) {
                square.x = 0;
            }
            if (square.x + square.width > canvas.width) {
                square.x = canvas.width - square.width;
            }
        }

        function draw() {
            // 1. Clear the canvas for the next frame
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // 2. Draw the square
            ctx.fillStyle = square.color;
            ctx.fillRect(square.x, square.y, square.width, square.height);
        }

        // --- Main Game Loop ---

        function gameLoop() {
            update();
            draw();

            // Request the next frame for smooth animation
            requestAnimationFrame(gameLoop);
        }

        // Start the game loop
        gameLoop();

    </script>

</body>
</html>
