<body>

    <div id="score">Score: 0</div>
    <canvas id="gameCanvas" width="600" height="400"></canvas>

    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');
        const scoreDisplay = document.getElementById('score');

        let score = 0;
        let squares = [];
        let targetColor = '';
        const COLORS = ['red', 'blue', 'green', 'yellow', 'purple'];
        const SQUARE_SIZE = 40;

        // --- Game State Management ---

        function updateScore(points) {
            score += points;
            scoreDisplay.textContent = `Score: ${score}`;
        }

        function generateNewTarget() {
            targetColor = COLORS[Math.floor(Math.random() * COLORS.length)];
        }

        function createSquare() {
            const x = Math.random() * (canvas.width - SQUARE_SIZE);
            const y = Math.random() * (canvas.height - SQUARE_SIZE);
            const color = COLORS[Math.floor(Math.random() * COLORS.length)];

            squares.push({
                x: x,
                y: y,
                color: color,
                id: Date.now() + Math.random() // Unique ID
            });
        }

        function draw() {
            // Clear the canvas
            ctx.clearRect(0, 0, canvas.width, canvas.height);

            // Draw the target color name
            ctx.fillStyle = '#000';
            ctx.font = '20px Arial';
            ctx.textAlign = 'center';
            ctx.fillText(`Match the ${targetColor.toUpperCase()}`, canvas.width / 2, 30);

            // Draw all squares
            squares.forEach(square => {
                ctx.fillStyle = square.color;
                ctx.fillRect(square.x, square.y, SQUARE_SIZE, SQUARE_SIZE);
            });
        }

        function initializeGame() {
            score = 0;
            squares = [];
            updateScore(0);
            generateNewTarget();

            // Start with 5 squares
            for (let i = 0; i < 5; i++) {
                createSquare();
            }
            draw();
        }

        // --- Interaction Logic ---

        function handleClick(event) {
            // Get click coordinates relative to the canvas
            const rect = canvas.getBoundingClientRect();
            const clickX = event.clientX - rect.left;
            const clickY = event.clientY - rect.top;

            let hitSquare = null;

            // Check if the click hits any existing square
            for (const square of squares) {
                if (clickX >= square.x && clickX <= square.x + SQUARE_SIZE &&
                    clickY >= square.y && clickY <= square.y + SQUARE_SIZE) {
                    hitSquare = square;
                    break;
                }
            }

            if (hitSquare) {
                // Check for match
                if (hitSquare.color === targetColor) {
                    updateScore(1);
                    // Remove the square
                    squares = squares.filter(s => s.id !== hitSquare.id);

                    // Generate a new square
                    createSquare();
                    generateNewTarget();
                } else {
                    // Incorrect match - penalize or do nothing
                    console.log("Incorrect match!");
                }
                draw(); // Redraw the canvas after state change
            }
        }

        // --- Initialization ---

        canvas.addEventListener('click', handleClick);
        initializeGame();

    </script>
</body>
</html>
