<body>

    <div id="game-container">
        <h1>Reaction Time Challenge</h1>
        <p>Click the box as fast as you can!</p>

        <div id="reaction-box">
            Click to Start
        </div>

        <div id="result">
            Waiting for the game to start...
        </div>

        <button id="startButton" onclick="startGame()">Start New Round</button>
    </div>

    <script>
        const reactionBox = document.getElementById('reaction-box');
        const resultDisplay = document.getElementById('result');
        const startButton = document.getElementById('startButton');

        let timeoutId = null;
        let startTime = null;
        let isTargetVisible = false;

        /**
         * Generates a random delay between 1 and 3 seconds (1000ms to 3000ms).
         * @returns {number} The random delay in milliseconds.
         */
        function getRandomDelay() {
            return Math.random() * 2000 + 1000; // 1000ms to 3000ms
        }

        /**
         * Starts a new round of the reaction time game.
         */
        function startGame() {
            // Reset state
            clearTimeout(timeoutId);
            isTargetVisible = false;
            reactionBox.classList.remove('ready');
            resultDisplay.textContent = 'Waiting for the target...';
            reactionBox.textContent = 'Click to Start';
            startButton.disabled = true;

            // Set up the target appearance
            const delay = getRandomDelay();

            // Set the timeout to make the box visible
            timeoutId = setTimeout(() => {
                showTarget();
            }, delay);
        }

        /**
         * Makes the reaction box visible and starts the timer.
         */
        function showTarget() {
            isTargetVisible = true;
            reactionBox.classList.add('ready');
            reactionBox.textContent = 'CLICK NOW!';

            // Record the exact time the target appeared
            startTime = performance.now();
        }

        /**
         * Handles the click event on the reaction box.
         * @param {Event} event 
         */
        reactionBox.addEventListener('click', function() {
            if (!isTargetVisible) {
                // Ignore clicks if the target hasn't appeared yet
                return;
            }

            // Record the time the player clicked
            const endTime = performance.now();

            // Calculate reaction time
            const reactionTime = endTime - startTime;

            // Display the result
            resultDisplay.innerHTML = `<strong>Reaction Time: ${reactionTime.toFixed(2)} ms</strong>`;

            // Reset the box appearance
            reactionBox.classList.remove('ready');
            reactionBox.textContent = 'Click to Start';
            startButton.disabled = false;
            isTargetVisible = false;
        });

    </script>

</body>
</html>
